import React, { createContext, useState, useContext, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AuthContext = createContext(null);

// 5 minutes in milliseconds
const INACTIVITY_TIMEOUT = 5 * 60 * 1000;

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
  const logoutTimer = useRef(null);
  const logoutRef = useRef(null);

  // Initialize axios instance with auth token
  const api = axios.create({
    baseURL: API_URL,
    headers: {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
    withCredentials: true, // Important for sending cookies
  });

  // Create a ref for the logout function to break the circular dependency
  const logout = useCallback(() => {
    // Clear tokens and user data using our utility
    clearAuthTokens();
    localStorage.removeItem('last_activity');
    setUser(null);

    // Clear any existing timers
    if (logoutTimer.current) {
      clearTimeout(logoutTimer.current);
      logoutTimer.current = null;
    }

    // Redirect to login page
    navigate('/login');
  }, [navigate]);

  // Store the logout function in a ref
  useEffect(() => {
    logoutRef.current = logout;
  }, [logout]);

  // Function to handle user activity
  const resetInactivityTimer = useCallback(() => {
    // Clear existing timer
    if (logoutTimer.current) {
      clearTimeout(logoutTimer.current);
    }

    // Set new timer
    logoutTimer.current = setTimeout(() => {
      console.log('User inactive for 5 minutes, logging out...');
      if (logoutRef.current) {
        logoutRef.current();
      }
    }, INACTIVITY_TIMEOUT);
  }, []);

  // Set up event listeners for user activity
  useEffect(() => {
    if (user) {
      // Add event listeners when user is logged in
      window.addEventListener('mousemove', resetInactivityTimer);
      window.addEventListener('keydown', resetInactivityTimer);
      window.addEventListener('mousedown', resetInactivityTimer);
      window.addEventListener('scroll', resetInactivityTimer);
      window.addEventListener('touchstart', resetInactivityTimer);

      // Start the timer
      resetInactivityTimer();

      // Clean up event listeners and timer
      return () => {
        window.removeEventListener('mousemove', resetInactivityTimer);
        window.removeEventListener('keydown', resetInactivityTimer);
        window.removeEventListener('mousedown', resetInactivityTimer);
        window.removeEventListener('scroll', resetInactivityTimer);
        window.removeEventListener('touchstart', resetInactivityTimer);

        if (logoutTimer.current) {
          clearTimeout(logoutTimer.current);
        }
      };
    }
  }, [user, resetInactivityTimer]);

  // Add request interceptor to add auth token to requests
  api.interceptors.request.use(
    (config) => {
      const token = getAccessToken();
      if (token) {
        config.headers['Authorization'] = `Bearer ${token}`;
      }
      return config;
    },
    (error) => {
      return Promise.reject(error);
    }
  );

  // Add response interceptor to handle token refresh
  api.interceptors.response.use(
    (response) => response,
    async (error) => {
      // Handle network errors (CORS, no internet, etc.)
      if (!error.response) {
        console.error('Network error:', error.message);
        return Promise.reject(error);
      }

      const originalRequest = error.config;

      // If error is 401 and we haven't tried to refresh yet
      if (error.response?.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;

        try {
          const refreshToken = localStorage.getItem('refresh_token');
          if (!refreshToken) {
            // No refresh token, log out
            logout();
            return Promise.reject(error);
          }

          // Try to refresh the token
          const response = await axios.post(`${API_URL}/auth/refresh-token`, {
            refresh_token: refreshToken
          });

          const { access_token, refresh_token } = response.data;

          // Update tokens in localStorage
          localStorage.setItem('access_token', access_token);
          if (refresh_token) {
            localStorage.setItem('refresh_token', refresh_token);
          }

          // Update the authorization header
          originalRequest.headers['Authorization'] = `Bearer ${access_token}`;

          // Retry the original request
          return api(originalRequest);
        } catch (err) {
          // Refresh token failed, log out
          logout();
          return Promise.reject(err);
        }
      }

      return Promise.reject(error);
    }
  );

  // Check if user is authenticated on initial load
  const checkAuth = useCallback(async () => {
    const token = getAccessToken();
    const lastActivity = localStorage.getItem('last_activity');

    // Check if token exists
    if (!token) {
      setIsLoading(false);
      return;
    }

    // Check if session is expired (5 minutes of inactivity)
    if (lastActivity) {
      const timeSinceLastActivity = Date.now() - parseInt(lastActivity, 10);
      if (timeSinceLastActivity > INACTIVITY_TIMEOUT) {
        console.log('Session expired due to inactivity');
        logout();
        setIsLoading(false);
        return;
      }
    }

    try {
      const response = await api.get('/auth/me');
      setUser(response.data);

      // Update last activity time on successful auth check
      localStorage.setItem('last_activity', Date.now().toString());

    } catch (err) {
      console.error('Auth check error:', err);

      // Handle rate limiting
      if (err.response?.status === 429) {
        console.warn('Rate limit exceeded for auth check');
        // Continue with the current session if we hit rate limit
        if (token) {
          setUser({ email: 'user@example.com' }); // Fallback user data
        }
      }
      // If token is invalid, clear it
      else if (err.response?.status === 401) {
        console.log('Invalid token, clearing auth data');
        logout();
      } else {
        // For other errors, just log them and continue with the current session
        console.error('Error checking auth status:', err);
        if (token) {
          setUser({ email: 'user@example.com' }); // Fallback user data
        }
      }
    } finally {
      setIsLoading(false);
    }
  }, [api, logout]);

  useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  const login = async (email, password, rememberMe = true) => {
    try {
      setError(null);
      const response = await api.post('/auth/token', new URLSearchParams({
        username: email,
        password: password,
      }), {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Accept': 'application/json',
        },
      });

      const { access_token, refresh_token, user: userData } = response.data;

      // Store tokens using our utility
      setAccessToken(access_token, rememberMe);
      if (refresh_token) {
        if (rememberMe) {
          localStorage.setItem('refresh_token', refresh_token);
        } else {
          sessionStorage.setItem('refresh_token', refresh_token);
        }
      }

      // Store login timestamp
      localStorage.setItem('last_activity', Date.now().toString());

      // Set user data
      setUser(userData);

      // Reset inactivity timer
      resetInactivityTimer();

      return userData;
    } catch (err) {
      console.error('Login error:', err);
      const errorMessage = err.response?.data?.detail || 'Login failed. Please check your credentials.';
      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  const register = async (userData) => {
    try {
      setError(null);
      const response = await api.post('/auth/register', userData);

      // Auto-login after registration
      if (userData.password) {
        await login(userData.email, userData.password);
      }

      return response.data;
    } catch (err) {
      console.error('Registration error:', err);
      const errorMessage = err.response?.data?.detail || 'Registration failed. Please try again.';
      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  const value = {
    user,
    isAuthenticated: !!user,
    isLoading,
    error,
    setError, // Expose setError to allow components to clear errors
    login,
    logout,
    register,
    api, // Export the configured axios instance
  };

  return (
    <AuthContext.Provider value={value}>
      {!isLoading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
